\label{th:2_exch}
GRO e-value for the exchangeability null \eqref{eq:exch_null_hyp} against an alternative $Q$ with density \(f_{T, \widetilde{T}}\) is
\begin{align*}
    E^{\mathrm{exch}} :&= \frac{
f_{T, \widetilde{T}}(T, \widetilde{T})
}{
\frac12\bigl(f_{T, \widetilde{T}}(T, \widetilde{T})+f_{T, \widetilde{T}}(\widetilde{T},T)\bigr)}\\&=1+\frac{f_{T, \widetilde{T}}(T, \widetilde{T})-f_{T, \widetilde{T}}(\widetilde{T}, T)}{f_{T, \widetilde{T}}(T, \widetilde{T})+f_{T, \widetilde{T}}(\widetilde{T}, T)}.
\end{align*}

\label{prop:mx_as_cond_exch}
$\mathcal{P}^{\text{X-CI}}_{K}$ is equivalent to the hypothesis
\begin{equation}
\label{eq:mx_as_cond_exch}
     \{P(\widetilde{X},X,Y,Z): (\widetilde{X},X,Y,Z) \overset{d}{=} (X, \widetilde{X},Y,Z),  P(\widetilde{X}|X,Y,Z) \sim K_Z \}
\end{equation}
in the sense that any distribution $P(X,Y,Z) \in \mathcal{P}^{\text{X-CI}}_{K}$ can be extended to an element of \eqref{eq:mx_as_cond_exch} by adding the additional variable $\widetilde{X}$ distributed as $K_Z$ given $(X,Y,Z)$, and conversely, any distribution $P(\widetilde{X},X,Y,Z)$ in \eqref{eq:mx_as_cond_exch} has an $(X,Y,Z)$-marginal that belongs to $\mathcal{P}^{\text{X-CI}}_{K}$.

Let $\mathcal{P}$ be a class of probability measures. A nonnegative random variable $E$ is an $(\epsilon,\delta)$-approximate e-variable for $\mathcal{P}$ if, for every $P\in\mathcal{P}$, there exists an event $A$ such that
\begin{align*}
\mathbb{E}_{P}\left[E\mathds{1}_{A}\right]
\leq 1+\epsilon
\qquad
\text{ and }
\qquad
P(A)
\geq 1-\delta.
\end{align*}

\label{def:approx_e_process}
Let $(E_t)_{t\geq 1}$ be a nonnegative process adapted to $(\mathcal{F}_t)_{t\geq 0}$, with $E_0=1$. We say that $(E_n)_{n\geq 1}$ is an ${(\epsilon_n,\delta_n)}_{t\geq1}$-approximate e-process for $\mathcal{P}$ if, for every $P\in\mathcal{P}$ and every $t\geq1$, there exists an event $A_n\in\mathcal{F}_n$ such that
\begin{align*}
\mathbb{E}_{P}
\left[
E_t\mathds{1}_{A_n}
\middle|
\mathcal{F}_{n-1}
\right]
&\leq
(1+\epsilon_n)E_{n-1},
\end{align*}
and
\begin{align*}
P(A_n\mid\mathcal{F}_{n-1})
\geq 1- \delta_n
\qquad\text{a.s.}
\end{align*}

Any $\hat{\eta}_n$ that is $\sigma\!\left(
Y_n, Z_n, \{(X_i, Y_i, Z_i)\}_{i=1}^{n-1}
\right)\text{-measurable}$ provides a valid exponential supermartingale. Similarly, any $\hat{\lambda}_n$ that is
$\sigma\!\left(
Y_n, Z_n, \{(X_i, Y_i, Z_i)\}_{i=1}^{n-1}
\right)\text{-measurable}$ provides a valid coin-betting supermartingale.\label{lemm:y_z_measu}

We denote by $\mathcal{D}_{n-1}:=\{(X_i, Y_i, Z_i)\}_{i=1}^{n-1}$ the previous observed data.

We observe that
\begin{align*}
    \mathbb{E}\left[\frac{\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(X, Z), Y\right)\right)}
{\mathbb{E}_{\widetilde{X} \mid Z}\!\left[\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(\widetilde{X}, Z), Y\right)\right)\right]}\right]&=\mathbb{E}\left[\mathbb{E}\left[\frac{\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(X, Z), Y\right)\right)}
{\mathbb{E}_{\widetilde{X} \mid Z}\!\left[\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(\widetilde{X}, Z), Y\right)\right)\right]}\mid Y, Z, \mathcal{D}_{n-1}\right]\right]\\&=\mathbb{E}\left[\mathbb{E}_{\widetilde{X} \mid Z}\left[\frac{\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(X, Z), Y\right)\right)}
{\mathbb{E}_{\widetilde{X} \mid Z}\!\left[\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(\widetilde{X}, Z), Y\right)\right)\right]}\right]\right]=1.
\end{align*}\label{rmk:depend_y_z}
The term $\mathbb{E}_{\widetilde{X} \mid Z}\left[\frac{\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(X, Z), Y\right)\right)}
{\mathbb{E}_{\widetilde{X} \mid Z}\!\left[\exp\!\left(-\widehat{\eta}\, l\!\left(\widehat{m}(\widetilde{X}, Z), Y\right)\right)\right]}\right]$ simplifies to 1 for every choice of $\widehat{\eta}(Y, Z)$ dependent on $Y, Z, \mathcal{D}_{n-1}$.

In this $0$--$1$ loss setting we can provide an explicit expression for the e-values
that optimize the e-power across the coin-betting and model-X classes, which
turn out to coincide.

We begin by optimizing $\eta$ for $E^\eta_{\mathrm{ML}}$. Observe that
\begin{align*}
\mathbb{E}_{X \mid Y,Z}\left[\log\left(E^\eta_{\mathrm{ML}}\right)\right]
&=
\mathbb{E}_{X \mid Y,Z}\left[
-\eta \mathds{1}_{\{m(X,Z)\neq Y\}}
-
\log
\mathbb{E}_{\widetilde{X}\mid Z}\left[
e^{-\eta \mathds{1}_{\{m(\widetilde X,Z)\neq Y\}}}
\right]
\right].
\end{align*}

Differentiating with respect to $\eta$ gives
\begin{align*}
-
\mathbb{E}_{X\mid Y,Z}\!\left[\mathds{1}_{\{m(X,Z)\neq Y\}}\right]
+
\frac{
\mathbb{E}_{\widetilde{X}\mid Z}\left[
\mathds{1}_{\{m(\widetilde X,Z)\neq Y\}}
e^{-\eta \mathds{1}_{\{m(\widetilde X,Z)\neq Y\}}}
\right]
}{
\mathbb{E}_{\widetilde{X}\mid Z}\left[
e^{-\eta \mathds{1}_{\{m(\widetilde X,Z)\neq Y\}}}
\right]
}.
\end{align*}

Let
\[
p_1 = P_{X\mid Y,Z}(m(X,Z)\neq Y \mid Y,Z),
\qquad
p_0 = P_{\widetilde X\mid Z}(m(\widetilde X,Z)\neq Y \mid Y,Z).
\]

Note that
\[
\mathbb{E}_{\widetilde{X}\mid Z}\left[
\mathds{1}_{\{m(\widetilde X,Z)\neq Y\}}
e^{-\eta \mathds{1}_{\{m(\widetilde X,Z)\neq Y\}}}
\right]
=
e^{-\eta} p_0.
\]

Thus the first-order condition becomes
\begin{align*}
-p_1
+
\frac{e^{-\eta_\star} p_0}{e^{-\eta_\star} p_0 + 1 - p_0}
=0.
\end{align*}

Solving yields
\begin{align*}
\eta_\star
=
\log
\frac{p_0(1-p_1)}{p_1(1-p_0)}.
\end{align*}

With this optimal $\eta_\star$, the e-variable $E^{\eta_\star}_{\mathrm{ML}}$
is
\begin{align*}
E^{\eta_\star}_{\mathrm{ML}}
&=
\frac{e^{-\eta_\star l(m(X,Z),Y)}}
{\mathbb{E}_{\widetilde{X}\mid Z}\left[e^{-\eta_\star l(m(\widetilde X,Z),Y)}\right]}
\\
&=
\frac{\left(e^{-\eta_\star}\right)^{\mathds{1}_{\{m(X,Z)\neq Y\}}}}
{p_0 e^{-\eta_\star} + 1 - p_0}
\\
&=
\frac{\left(\frac{p_1(1-p_0)}{p_0(1-p_1)}\right)^{\mathds{1}_{\{m(X,Z)\neq Y\}}}}
{p_0\frac{p_1(1-p_0)}{p_0(1-p_1)} + 1 - p_0}
\\
&=
\left(
\frac{p_1(1-p_0)}{p_0(1-p_1)}
\right)^{\mathds{1}_{\{m(X,Z)\neq Y\}}}
\frac{1-p_1}{1-p_0}.
\end{align*}

Therefore, there are two cases:
\[
E =
\begin{cases}
\dfrac{1-p_1}{1-p_0}, & m(X,Z)=Y, \\
\dfrac{p_1}{p_0}, & m(X,Z)\neq Y.
\end{cases}
\]

\medskip

We can proceed similarly for the coin-betting e-value. Optimizing
$\lambda$ yields
\[
\lambda_\star
=
\frac{p_1-p_0}{p_0(p_0-1)}.
\]

Substituting this value into the e-variable gives two cases.

If the prediction is correct, $Y=m(X,Z)$, then
\[
E_{\mathrm{CB}}
=
1+\lambda_\star p_0
=
1+\frac{p_1-p_0}{p_0-1}
=
\frac{1-p_1}{1-p_0}.
\]

If the prediction is incorrect,
\[
E_{\mathrm{CB}}
=
1+\frac{p_1-p_0}{p_0(p_0-1)}(p_0-1)
=
\frac{p_1}{p_0}.
\]

Thus the coin-betting and model-X optimal e-variables coincide.

Let $P(X,Y,Z)$ be any distribution from the original representation of $\mathcal{P}^{\text{MX-CI}}_{K}$, and  $P'(\widetilde{X},X,Y,Z) := K_Z \otimes P(X,Y,Z)$, then by construction $P'(\widetilde{X}|X,Y,Z) \sim K_Z$, $X \perp\!\!\!\perp \widetilde{X}|Y,Z$ and $P'(X|Y,Z) = P'(\widetilde{X}|Y,Z)$. Now, 
\begin{equation*}
   P'(\widetilde{X},X,Y,Z) = P(\widetilde{X}|X,Y,Z) \otimes P(X|Y,Z) \otimes P(Y,Z) =  K_Z \otimes K_Z \otimes P(Y,Z) = P'(X,\widetilde{X},Y,Z),
\end{equation*}
meaning that $P'$ is an element of \eqref{eq:mx_as_cond_exch}.

On the other hand, if we start with a $P'(\widetilde{X},X,Y,Z)$, from \eqref{eq:mx_as_cond_exch}, using exchangeability we immediately get $P'(X|\widetilde{X},Y,Z) = K_Z$ implying $X \perp\!\!\!\perp_{P'} Y | Z$ and $P'(X|Z) = K_Z$, meaning that the marginal $P'(X,Y,Z)$ belongs to the original representation of the null.

Any statistic $S$ that is $Q$-a.s. equal to the likelihood ratio of the point alternative distribution $Q$ and an element of the null hypothesis satisfies the following:\\
If $S$ is an e-variable for the null, then $S$ is a version of the GRO e-variable for testing against $Q$ \citep{numeraire}. All e-variables in Table \ref{tab:null-distillation} can be rewritten in such a form by extending the conditional likelihood ratio to a full likelihood ratio where necessary. Thus, all that remains is to check the e-variable property for each. The first null is treated in \citet{Grünwald02042024}, and the argument for the second is analogous:\\
Let $P \in \mathcal{P}^{\textnormal{PFX-CI}}_K$, then $P(T\mid Y,Z) = P(\widetilde{T}\mid Y,Z) = K^\#(\cdot\mid Y, Z)$, which has density function $f_{\widetilde{T}|Y,Z}$ by the model-X assumption on the alternative, and thus
\begin{equation*}
    \mathbb{E}_P\left[ \frac{f_{T|Y,Z}(T|Y,Z)}{f_{\widetilde{T}|Y,Z}(T|Y,Z)} \middle| Y,Z \right] = 1.
\end{equation*}
The e-variable property follows by the tower property of conditional expectations.\\
Exchangeability, conditional exchangeability and symmetry can all be proved using the same symmetry argument. We will explicitly show it for $B$-exchangeability only. For any exchangeable distribution $P(T,\widetilde{T}^B)$ and $(B+1)$-permutation $\sigma'$, we have:
\begin{align*}
    \mathbb{E}_{P(T,\widetilde{T}^B)} \left[ \frac{f_{T,\widetilde{T}^B}(T,\widetilde{T}^B)}{\frac{1}{(B+1)!} \sum_{\sigma} f_{T,\widetilde{T}^B}(\sigma(T,\widetilde{T}^B))} \right] &= \mathbb{E}_{P(\sigma'(T,\widetilde{T}^B))} \left[ \frac{f_{T,\widetilde{T}^B}(T,\widetilde{T}^B)}{\frac{1}{(B+1)!} \sum_{\sigma} f_{T,\widetilde{T}^B}(\sigma(T,\widetilde{T}^B))} \right] \\
    &= \mathbb{E}_{P(T,\widetilde{T}^B)} \left[ \frac{f_{T,\widetilde{T}^B}(\sigma'^{-1}(T,\widetilde{T}^B))}{\frac{1}{(B+1)!} \sum_{\sigma} f_{T,\widetilde{T}^B}(\sigma(T,\widetilde{T}^B))} \right]
\end{align*}
Thus, the proposed e-variable has the same expectation under $P$ for any permutation of its arguments. Summing over all $(B+1)!$ choices of $\sigma'$ gives us exactly the value $(B+1)!$, meaning that the original expectation must be exactly $1$.

\label{prop:rb_monotonically_increases_power}
Let $T, \widetilde{T}^B$ all be conditionally independent given $(Y,Z)$, and $\widetilde{T}^B$ further identically distributed. Let $S(T,\widetilde{T})$ be a non-negative statistic and $S^B(T,\widetilde{T}^B):= \frac{1}{B}\sum_{i=1}^B S(T,\widetilde{T}_i)$, then the sequence

\begin{equation*}
    \mathbb{E}\left[\ln\left(S^B(T,\widetilde{T}^B)\right)\right]
\end{equation*}
is monotonically increasing in $B$.

Notice that 
\begin{equation*}
    S^B(T,\widetilde{T}^B) = \frac{1}{B} \sum _{i=1}^B S^{B-1}(T,\widetilde{T}^{B}_{-i}),
\end{equation*}
where $\widetilde{T}^{B}_{-i}$ is $\widetilde{T}^{B}$ without component $i$. Therefore, by Jensen's inequality 
\begin{equation*}
    \mathbb{E}\left[\ln\left(S^B(T,\widetilde{T}^B)\right)\right] \geq \frac{1}{B} \sum_{i=1}^B \mathbb{E}\left[\ln\left(S^{B-1}(T,\widetilde{T}^B_{-i})\right)\right] = \mathbb{E}\left[\ln\left(S^{B-1}(T,\widetilde{T}^{B-1})\right)\right].
\end{equation*}
In the last equality we used the conditional independence and i.i.d. property.

Assuming that under the point alternative $Q( \widetilde{T}^B,T,Y,Z)$ with density function $f$,  $T, \widetilde{T}^B$  are all conditionally independent given $(Y,Z)$, and that the $\widetilde{T}_i$ are conditionally identically distributed, we have:
\begin{align*}
    E^{\text{cond exch}}_B(t,\widetilde{t}^B,y,z) &= \frac{f_{T|Y,Z}(t|y,z)\prod_{i=1}^B f_{\widetilde{T}|Y,Z}(\widetilde{t}_i|y,z)}{\frac{1}{B+1} (f_{T|Y,Z}(t|y,z)\underset{i=1}{\overset{B}{\prod}} f_{\widetilde{T}|Y,Z}(\widetilde{t}_i|y,z) + f_{\widetilde{T}|Y,Z}(t|y,z) \overset{B}{\underset{j=1}{\sum}} f_{T|Y,Z}(\widetilde{t}_j|y,z)  \underset{i\neq j}{\prod} f_{\widetilde{T}|Y,Z}(\widetilde{t}_i|y,z))} \\
    &= \frac{f_{T|Y,Z}(t|y,z)}{\frac{1}{B+1} (f_{T|Y,Z}(t|y,z) + f_{\widetilde{T}|Y,Z}(t|y,z) \sum _{j=1}^B \frac{f_{T|Y,Z}(\widetilde{t}_j|y,z)}{f_{\widetilde{T}|Y,Z}(\widetilde{t}_j|y,z)}) }.
\end{align*}

First, we simply factorized the joint densities into products using conditional independence under the alternative, and noticed that, by symmetry, the sum of $(B+1)!$ terms simplifies into a smaller sum of $(B+1)$ terms. To get the second equality we divide everything by the product in the numerator.
Now, note that if we evaluate this e-variable in the random vector $(T, \widetilde{T}_1,...,\widetilde{T}_B)$ and let $B$ tend to infinity, by an application of the strong law of large numbers in the denominator, the limiting random variable is $Q$-a.s. equal to 
\begin{equation*}
    \frac{f_{T|Y,Z}(T|Y,Z)}{f_{\widetilde{T}|Y,Z}(T|Y,Z) \cdot \mathbb{E}_{Q}\left[ \frac{f_{T|Y,Z}(\widetilde{T}|Y,Z)}{f_{\widetilde{T}|Y,Z}(\widetilde{T}|Y,Z)} \middle|Y,Z \right]} = \frac{f_{T|Y,Z}(T|Y,Z)}{f_{\widetilde{T}|Y,Z}(T|Y,Z)}.
\end{equation*}

\label{prop:cond_exch_e_power_seq}
The sequence of e-powers
\begin{equation*}
    \mathbb{E}_Q\left[\ln\left(E^{\textnormal{cond exch}}_B\right)\right]
\end{equation*}
is (weakly) increasing in $B$ with limit 
\begin{equation*}
    \mathbb{E}_{Q(Y,Z)}\left[D_{\text{KL}}\left(Q(T|Y,Z) || Q(\widetilde{T}|Y,Z)\right)\right],
\end{equation*}
whenever the latter expectation is finite.

Throughout, $(Y,Z)$ denotes the realized value, so that given $(Y,Z)$ the $\widetilde{T}_j$ are i.i.d.\ with density $f_{\widetilde{T}|Y,Z}(\cdot\mid Y,Z)$ and $T$ has density $f_{T|Y,Z}(\cdot\mid Y,Z)$, while lowercase $(y,z)$ is an integration variable. By Assumption 2, $f_{T|Y,Z}(t\mid y,z)=w(t\mid y,z)\,f_{\widetilde{T}|Y,Z}(t\mid y,z)$ for all $t,y,z$.


\textbf{Step 1 (rewriting the e-variable).}
Using the same product decomposition as in $E_B^{\text{cond exch}}$ (see Appendix \ref{sect:limiting_gro_cond_exch}), but marginalizing over $y$ and $z$,

\begin{align*}
     &E_B^{\text{exch}}(t,\widetilde{t}^B) \\
     &=\frac{(B+1)\int f_{T|Y,Z}(t\mid y,z)\prod_{i=1}^B f_{\widetilde{T}|Y,Z}(\widetilde{t}_i\mid y,z)\, f_{Y,Z}(y,z)\,dy\,dz}{
      \int \Bigl[f_{T|Y,Z}(t\mid y,z)\overset{B}{\underset{i=1}{\prod}} f_{\widetilde{T}|Y,Z}(\widetilde{t}_i\mid y,z)
     +  f_{\widetilde{T}|Y,Z}(t\mid y,z) \overset{B}{\underset{j=1}{\sum}}f_{T|Y,Z}(\widetilde{t}_j\mid y,z) \underset{i\neq j}{\prod} f_{\widetilde{T}|Y,Z}(\widetilde{t}_i\mid y,z)\Bigr] f_{Y,Z}(y,z)\,dy\,dz.}
\end{align*}

Since $f_{T|Y,Z}(\widetilde{t}_j\mid y,z)\prod_{i\neq j}f_{\widetilde{T}|Y,Z}(\widetilde{t}_i\mid y,z)=w(\widetilde{t}_j\mid y,z)\prod_{i}f_{\widetilde{T}|Y,Z}(\widetilde{t}_i\mid y,z)$, dividing numerator and denominator by $(B+1)\int\prod_{i}f_{\widetilde{T}|Y,Z}(\widetilde{t}_i\mid y,z)f_{Y,Z}(y,z)\,dy\,dz$ and using Bayes' rule gives
\begin{equation}\label{eq:EB-rewritten}
    E_B^{\text{exch}}(t,\widetilde{t}^B)=\frac{A_B(t)}{\frac{1}{B+1}A_B(t)+D_B(t)},
\end{equation}
where
\begin{align*}
    A_B(t)&=\int f_{T|Y,Z}(t\mid y,z)\,f_{Y,Z\mid\widetilde{T}^B}(y,z\mid\widetilde{t}^B)\,dy\,dz,\\
    D_B(t)&=\int f_{\widetilde{T}|Y,Z}(t\mid y,z)\left(\frac{1}{B+1}\sum_{j=1}^B w(\widetilde{t}_j\mid y,z)\right)f_{Y,Z\mid\widetilde{T}^B}(y,z\mid\widetilde{t}^B)\,dy\,dz.
\end{align*}
From now on we evaluate at $\widetilde{t}^B=\widetilde{T}^B$.

\textbf{Step 2 ($A_B$-term).}
For fixed $t$, the function $(y,z)\mapsto f_{T|Y,Z}(t\mid y,z)$ is continuous and bounded by $C$ (Assumption 1). Hence, by the definition of weak convergence and Assumption 3,
\[
    A_B(t)\to\int f_{T|Y,Z}(t\mid y,z)\,\Pi_{\varphi(Y,Z)}(dy,dz)=f_{T|\varphi(Y,Z)}(t\mid\varphi(Y,Z)),
    \qquad\text{and}\qquad \frac{A_B(t)}{B+1}\le\frac{C}{B+1}\to0 .
\]

\textbf{Step 3 (the likelihood-ratio average converges uniformly in $(y,z)$).}
Let
\[
    \overline{w}_B(y,z)\overset{ \mathrm{def}}{=}\frac1B\sum_{j=1}^B w(\widetilde{T}_j\mid y,z),
    \qquad
    r(y,z)\overset{\mathrm{def}}{=}\int w(t'\mid y,z)\,f_{\widetilde{T}|Y,Z}(t'\mid Y,Z)\,dt',
\]
so that $r(y,z)$ is the mean of $w(\widetilde{T}_j\mid y,z)$. By Assumption 2,
$|r(y,z)-r(y',z')|\le \ell(Y,Z)\, ||(y,z) - (y',z')||$. Moreover $r(Y,Z)=\int f_{T|Y,Z}(t'\mid Y,Z)\,dt'=1$, so $r$ is bounded by $1+\ell(Y,Z)\cdot\operatorname{diam}<\infty$. We show that, almost surely,
\begin{equation}\label{eq:ULLN}
    \sup_{y,z}\,\bigl|\overline{w}_B(y,z)-r(y,z)\bigr|\to0 .
\end{equation}
Fix $\delta>0$. By compactness, the space of $(y,z)$ is covered by finitely many balls of radius $\delta$, with centres $(y_1,z_1),\dots,(y_K,z_K)$. By the strong law of large numbers (applied to finitely many i.i.d.\ sequences with finite means), almost surely
\[
    \overline{w}_B(y_k,z_k)\to r(y_k,z_k)\ \ (k=1,\dots,K),
    \qquad
    \frac1B\sum_{j=1}^B L(\widetilde{T}_j)\to\ell(Y,Z) .
\]
For any $(y,z)$, choose $k$ with $||(y,z)-(y_k,z_k)||<\delta$. Using Assumption 2 twice,
\begin{align*}
    \bigl|\overline{w}_B(y,z)-r(y,z)\bigr|
    &\le \bigl|\overline{w}_B(y,z)-\overline{w}_B(y_k,z_k)\bigr| + \bigl|\overline{w}_B(y_k,z_k)-r(y_k,z_k)\bigr| + \bigl|r(y_k,z_k)-r(y,z)\bigr| \\
    &\le \delta\,\frac1B\sum_{j=1}^B L(\widetilde{T}_j) + \max_{k\le K}\bigl|\overline{w}_B(y_k,z_k)-r(y_k,z_k)\bigr| + \delta\,\ell(Y,Z) .
\end{align*}
The right-hand side does not depend on $(y,z)$, and its $\limsup$ is $2\delta\,\ell(Y,Z)$. Since $\delta$ was arbitrary, we get \eqref{eq:ULLN}.

\textbf{Step 4 ($D_B$-term).}
Since $\frac{1}{B+1}\sum_{j=1}^B w(\widetilde{T}_j\mid y,z)=\frac{B}{B+1}\overline{w}_B(y,z)$, we can split
\begin{multline*}
    \frac{B+1}{B}\,D_B(t)=\int f_{\widetilde{T}|Y,Z}(t\mid y,z)\,r(y,z)\,f_{Y,Z\mid\widetilde{T}^B}(y,z\mid\widetilde{T}^B)\,dy\,dz\\
    +\int f_{\widetilde{T}|Y,Z}(t\mid y,z)\bigl(\overline{w}_B(y,z)-r(y,z)\bigr)\,f_{Y,Z\mid\widetilde{T}^B}(y,z\mid\widetilde{T}^B)\,dy\,dz.
\end{multline*}
The second term is at most $C\sup_{y,z}|\overline{w}_B(y,z)-r(y,z)|$ in absolute value, which tends to $0$ by \eqref{eq:ULLN}. In the first term, $(y,z)\mapsto f_{\widetilde{T}|Y,Z}(t\mid y,z)\,r(y,z)$ is continuous and bounded (Assumption 1 and Step 3), so by Assumption 3 it converges to $\int f_{\widetilde{T}|Y,Z}(t\mid y,z)\,r(y,z)\,\Pi_{\varphi(Y,Z)}(dy,dz)$. For every $(y,z)$ in the fiber, $Q(\widetilde{T}|Y=y,Z=z)=Q(\widetilde{T}|Y=Y,Z=Z)$, and therefore
\[
    f_{\widetilde{T}|Y,Z}(t\mid y,z)=f_{\widetilde{T}|Y,Z}(t\mid Y,Z),
    \qquad
    r(y,z)=\int w(t'\mid y,z)\,f_{\widetilde{T}|Y,Z}(t'\mid y,z)\,dt'=\int f_{T|Y,Z}(t'\mid y,z)\,dt'=1 .
\]
Since $\Pi_{\varphi(Y,Z)}$ is supported on the fiber, $D_B(t)\to f_{\widetilde{T}|Y,Z}(t\mid Y,Z)$.

\textbf{Step 5 (conclusion).}
The almost-sure events used in Steps 2--4 (Assumption 3, and the countably many strong laws in Step 3) do not depend on $t$. Hence, almost surely, Steps 2 and 4 hold simultaneously for all $t$, and in particular for $t=T$. Moreover $f_{\widetilde{T}|Y,Z}(T\mid Y,Z)>0$ a.s., because $T$ has density $f_{T|Y,Z}(\cdot\mid Y,Z)$, which vanishes wherever $f_{\widetilde{T}|Y,Z}(\cdot\mid Y,Z)$ does (Assumption 2). Plugging Steps 2 and 4 into \eqref{eq:EB-rewritten},
\begin{equation*}
    \lim_{B \to \infty} E_B^{\text{exch}}(T,\widetilde{T}^B)
    = \frac{\int f_{T|Y,Z}(T\mid y,z)\, \Pi_{\varphi(Y,Z)}(dy,dz)}{ f_{\widetilde{T}|Y,Z}(T\mid Y,Z) }
    = \frac{f_{T|\varphi(Y,Z)}(T\mid\varphi(Y,Z))}{  f_{\widetilde{T}|Y,Z}(T\mid Y,Z)}.
    \qedhere
\end{equation*}

Define the cumulative inflated-controlled event

$G_n
:=
\bigcap_{t=1}^n A_n.$ 

By the definition of the approximate e-process,
\begin{align*}
\mathbb{E}_{P}
\left[
E_n\mathds{1}_{G_n}
\middle|
\mathcal{F}_{n-1}
\right]
=
\mathds{1}_{G_{n-1}}
\mathbb{E}_{P}
\left[
E_n\mathds{1}_{A_n}
\middle|
\mathcal{F}_{n-1}
\right]
\leq
(1+\epsilon_n)
\mathds{1}_{G_{n-1}}E_{n-1}.
\end{align*}

Define
\begin{align*}
M_n
:=
\frac{
E_{n}\mathds{1}_{G_n}
}{
\prod_{t=1}^n(1+\epsilon_n)
}.
\end{align*}
Then $(M_n)_{n\geq0}$ is a nonnegative supermartingale with $M_0=1$. By Ville's inequality,
\begin{align*}
P
\left(
\sup_{1\leq n\leq N}M_n
\geq \frac{1}{\alpha}
\right)
\leq \alpha.
\end{align*}

Let
\begin{align*}
C_N
:=
\prod_{t=1}^N(1+\epsilon_n).
\end{align*}
On the event $G_N$, for every $n\leq N$,
\begin{align*}
E_{n}
&\leq
C_N M_n.
\end{align*}
Consequently,
\begin{align*}
\left\{
\sup_{1\leq n\leq N}
E_{n}
\geq \frac{1}{\alpha}
\right\}\cap G_N
&\subseteq
\left\{
\sup_{1\leq n\leq N}
M_n
\geq
\frac{1}{\alpha C_N}
\right\}.
\end{align*}
Applying Ville's inequality at level $\alpha C_N$ gives
\begin{align*}
P
\left(
\sup_{1\leq n\leq N}
E_n
\geq \frac{1}{\alpha},
\ G_N
\right)
&\leq
\alpha C_N.
\end{align*}

It remains to control the probability that at least one of the events $A_n$ fails. By the probability assumption on the approximate e-process definition and union bound,
\begin{align*}
P(G_N^c)
=
P
\left(
\bigcup_{n=1}^N A_n^c
\right)
\
\leq
\sum_{n=1}^N
P(A_n^c)
\
\leq
\sum_{n=1}^N\delta_n.
\end{align*}
Therefore,
\begin{align*}
P
\left(
\sup_{1\leq n\leq N}
E_n
\geq \frac{1}{\alpha}
\right)
&\leq
\sum_{n=1}^N\delta_n
+
\alpha
\prod_{t=1}^N(1+\epsilon_n).
\end{align*}

Finally, since $\log(1+x)\leq x$ for all $x\geq0$,
\begin{align*}
\prod_{t=1}^N(1+\epsilon_n)
=
\exp\left(
\sum_{n=1}^N\log(1+\epsilon_n)
\right)\leq
\exp\left(
\sum_{n=1}^N\epsilon_n
\right).
\end{align*}
This proves the result.
